import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { ProductService } from '../../services/product.service';
import { Product, Category, Banner } from '../../models/product.model';

@Component({
  selector: 'app-landing',
  standalone: true,
  imports: [CommonModule, RouterLink],
  template: `
    <div class="container">
      <!-- Banners Section -->
      <section class="banners" *ngIf="banners.length > 0">
        <div class="banner" *ngFor="let banner of banners">
          <img [src]="banner.image" [alt]="banner.title" class="banner-img">
          <div class="banner-content">
            <h2>{{ banner.title }}</h2>
            <p>{{ banner.description }}</p>
            <span class="discount-badge" *ngIf="banner.discount_offer">
              {{ banner.discount_offer }}
            </span>
          </div>
        </div>
      </section>

      <!-- Categories Section -->
      <section class="categories mt-4">
        <h2 class="text-center mb-3">Shop by Category</h2>
        <div class="grid">
          <div class="card" *ngFor="let category of categories" [routerLink]="['/products']" [queryParams]="{category: category.id}">
            <img [src]="category.image || 'assets/placeholder.jpg'" [alt]="category.display_name" class="card-img">
            <div class="card-body">
              <h3 class="card-title">{{ category.display_name }}</h3>
              <p class="card-text">{{ category.products_count }} products</p>
            </div>
          </div>
        </div>
      </section>

      <!-- Featured Products -->
      <section class="featured-products mt-4">
        <h2 class="text-center mb-3">Featured Products</h2>
        <div class="grid">
          <div class="card" *ngFor="let product of featuredProducts" [routerLink]="['/products', product.id]">
            <img [src]="product.image" [alt]="product.name" class="card-img">
            <div class="card-body">
              <h3 class="card-title">{{ product.title }}</h3>
              <div class="price-section">
                <span class="price-original" *ngIf="product.discounted_price">₹{{ product.price }}</span>
                <span class="price">₹{{ product.final_price }}</span>
                <span class="discount-badge" *ngIf="product.discount_percentage > 0">
                  {{ product.discount_percentage }}% OFF
                </span>
              </div>
              <p class="card-text">{{ product.purity }}</p>
            </div>
          </div>
        </div>
      </section>
    </div>
  `,
  styles: [`
    .banners {
      margin: 2rem 0;
    }

    .banner {
      position: relative;
      border-radius: 8px;
      overflow: hidden;
      margin-bottom: 2rem;
    }

    .banner-img {
      width: 100%;
      height: 400px;
      object-fit: cover;
    }

    .banner-content {
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      background: linear-gradient(transparent, rgba(0,0,0,0.8));
      color: white;
      padding: 2rem;
    }

    .price-section {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      margin: 0.5rem 0;
    }
  `]
})
export class LandingComponent implements OnInit {
  categories: Category[] = [];
  featuredProducts: Product[] = [];
  banners: Banner[] = [];

  constructor(private productService: ProductService) {}

  ngOnInit(): void {
    this.loadCategories();
    this.loadFeaturedProducts();
    this.loadBanners();
  }

  loadCategories(): void {
    this.productService.getCategories().subscribe({
      next: (data) => this.categories = data,
      error: (err) => console.error('Error loading categories:', err)
    });
  }

  loadFeaturedProducts(): void {
    this.productService.getFeaturedProducts().subscribe({
      next: (data) => this.featuredProducts = data,
      error: (err) => console.error('Error loading featured products:', err)
    });
  }

  loadBanners(): void {
    this.productService.getBanners().subscribe({
      next: (data) => this.banners = data,
      error: (err) => console.error('Error loading banners:', err)
    });
  }
}

